cssCode:
.h-scroll-wrap {
  height: 300vh; /* ઊભું સ્ક્રોલ કરવા માટે */
  position: relative;
}
.h-sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  width: 100%;
  overflow: hidden;
  display: flex;
  align-items: center;
}
.h-container {
  display: flex;
  width: 300vw; /* 3 પેજ જેટલી પહોળાઈ */
  height: 80vh;
  transition: transform 0.1s linear;
}
.h-slide {
  width: 100vw;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 50px;
  font-weight: bold;
  color: #fff;
  font-family: sans-serif;
}
.slide-1 { background: linear-gradient(45deg, #ff007f, #6c63ff); }
.slide-2 { background: linear-gradient(45deg, #00d2ff, #3a7bd5); }
.slide-3 { background: linear-gradient(45deg, #00ffcc, #00997a); }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#1a1a2e;overflow-x:hidden;';

const wrap = document.createElement('div');
wrap.className = 'h-scroll-wrap';

const sticky = document.createElement('div');
sticky.className = 'h-sticky';

const hContainer = document.createElement('div');
hContainer.className = 'h-container';

['1. INNOVATION', '2. DESIGN', '3. TECHNOLOGY'].forEach((txt, i) => {
  const slide = document.createElement('div');
  slide.className = `h-slide slide-${i+1}`;
  slide.innerText = txt;
  hContainer.appendChild(slide);
});

sticky.appendChild(hContainer);
wrap.appendChild(sticky);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const maxScroll = c.scrollHeight - c.clientHeight;
  const progress = c.scrollTop / maxScroll;

  // ઊભા સ્ક્રોલને આડા (Horizontal) સ્ક્રોલમાં ફેરવવું
  const xTranslate = progress * 200; // 3 સ્લાઈડ છે એટલે 200vw ખસશે
  hContainer.style.transform = `translateX(-${xTranslate}vw)`;
});
